/**
 * Minimal CSV writer. Kept separate from the pages that use it so the escaping
 * rules — which are a security control, not formatting — stay unit-tested.
 */

export interface CsvColumn<T> {
  header: string;
  /** Cell value; objects should be stringified by the caller. */
  value: (row: T) => unknown;
}

/** Leading chars a spreadsheet treats as the start of a formula. */
const FORMULA_START = /^[=+\-@]/;

function escapeCell(raw: unknown): string {
  if (raw === null || raw === undefined) return "";
  let s = String(raw);
  // Formula-injection guard: a leading quote makes Excel/Sheets treat it as text.
  if (FORMULA_START.test(s)) s = `'${s}`;
  if (/[",\r\n]/.test(s)) s = `"${s.replaceAll('"', '""')}"`;
  return s;
}

/** Pure: rows + column defs -> CSV text (header row first, LF line endings). */
export function toCsv<T>(rows: readonly T[], columns: readonly CsvColumn<T>[]): string {
  const lines = [columns.map((c) => escapeCell(c.header)).join(",")];
  for (const row of rows) {
    lines.push(columns.map((c) => escapeCell(c.value(row))).join(","));
  }
  return lines.join("\n");
}
