/**
 * "Add MKR Gas to your home screen" banner.
 *
 * Captures the standard `beforeinstallprompt` event, lets the user accept or
 * dismiss, and remembers the dismissal locally so we never nag the same
 * browser twice. iOS Safari does not fire the event but it does support
 * Add-to-Home-Screen via the share menu, so we show a one-line hint on iOS
 * the first time the user opens the app instead.
 */
import { useEffect, useState } from "react";
import { Download, X } from "lucide-react";

import { Button } from "@/components/ui/button";

interface BeforeInstallPromptEvent extends Event {
  prompt: () => Promise<void>;
  userChoice: Promise<{ outcome: "accepted" | "dismissed" }>;
}

const DISMISS_KEY = "mkrgas:pwa-install-dismissed";

function isStandalone(): boolean {
  if (typeof window === "undefined") return false;
  if (window.matchMedia("(display-mode: standalone)").matches) return true;
  if ("standalone" in window.navigator && (window.navigator as unknown as { standalone: boolean }).standalone)
    return true;
  return false;
}

function isIos(): boolean {
  if (typeof navigator === "undefined") return false;
  return /iPhone|iPad|iPod/i.test(navigator.userAgent) && !/CriOS|FxiOS/.test(navigator.userAgent);
}

export function PwaInstallBanner() {
  const [event, setEvent] = useState<BeforeInstallPromptEvent | null>(null);
  const [iosHint, setIosHint] = useState(false);
  const [dismissed, setDismissed] = useState<boolean>(() => {
    if (typeof window === "undefined") return true;
    return window.localStorage.getItem(DISMISS_KEY) === "1";
  });

  useEffect(() => {
    if (dismissed || isStandalone()) return;
    function onBeforeInstall(e: Event) {
      e.preventDefault();
      setEvent(e as BeforeInstallPromptEvent);
    }
    function onInstalled() {
      setEvent(null);
      setDismissed(true);
      try {
        window.localStorage.setItem(DISMISS_KEY, "1");
      } catch {
        /* ignore */
      }
    }
    window.addEventListener("beforeinstallprompt", onBeforeInstall);
    window.addEventListener("appinstalled", onInstalled);
    if (isIos()) setIosHint(true);
    return () => {
      window.removeEventListener("beforeinstallprompt", onBeforeInstall);
      window.removeEventListener("appinstalled", onInstalled);
    };
  }, [dismissed]);

  function dismiss() {
    setDismissed(true);
    setEvent(null);
    setIosHint(false);
    try {
      window.localStorage.setItem(DISMISS_KEY, "1");
    } catch {
      /* ignore */
    }
  }

  async function accept() {
    if (!event) return;
    await event.prompt();
    const { outcome } = await event.userChoice;
    if (outcome === "accepted" || outcome === "dismissed") {
      dismiss();
    }
  }

  if (dismissed || isStandalone()) return null;
  if (!event && !iosHint) return null;

  return (
    <div className="fixed bottom-4 left-1/2 z-40 w-[calc(100%-2rem)] max-w-md -translate-x-1/2 rounded-lg border bg-card/95 p-3 shadow-lg backdrop-blur supports-[backdrop-filter]:bg-card/80">
      <div className="flex items-start gap-3">
        <div className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-md bg-emerald-500/20 text-emerald-500">
          <Download className="h-4 w-4" />
        </div>
        <div className="flex-1 space-y-1">
          <div className="text-sm font-medium">Install MKR Gas</div>
          {iosHint && !event ? (
            <p className="text-xs text-muted-foreground">
              Tap the <span className="font-medium">Share</span> button, then{" "}
              <span className="font-medium">Add to Home Screen</span> for a native-feeling
              shortcut.
            </p>
          ) : (
            <p className="text-xs text-muted-foreground">
              Add a one-tap shortcut to your home screen and open it like a native app.
            </p>
          )}
        </div>
        <div className="flex items-center gap-1">
          {event ? (
            <Button size="sm" onClick={accept}>
              Install
            </Button>
          ) : null}
          <Button size="icon" variant="ghost" onClick={dismiss}>
            <X className="h-4 w-4" />
          </Button>
        </div>
      </div>
    </div>
  );
}
