/**
 * Where you sit in the local market, from human sign-readings.
 *
 * Everything here is pure. The one rule that matters: an observation nobody
 * has refreshed in a day is not evidence about today's market, so it is
 * dropped rather than averaged in. A rank computed from one stale reading
 * looks exactly as confident as a real one, which is the trap.
 */
import type { CompetitorPricesFile } from "./types";

/**
 * Observations older than this never feed a rank/average. Deliberately longer
 * than the 12h `STALE_AFTER_MS` used to *label* a capture — a 14h-old sign is
 * worth flagging to the person capturing, but still worth counting today.
 */
export const FRESH_WINDOW_MS = 24 * 60 * 60 * 1000;

/** Alert thresholds in cents/L — roadside units, the ones the owner thinks in. */
export const UNDERCUT_CENTS = 2; // you are this far ABOVE the cheapest nearby → volume risk
export const BELOW_AVERAGE_CENTS = 2; // this far BELOW the nearby average → margin on the table

export interface Observation {
  competitorId: string;
  pricePerL: number;
  /** When the sign was actually read. Missing = unusable for freshness. */
  observedAt?: string;
}

export interface MarketPosition {
  yourPerL: number;
  cheapestPerL: number;
  averagePerL: number;
  /** 1-based, counting you among the fresh competitors. Ties share the better rank. */
  rank: number;
  /** You + the competitors that had a fresh reading. */
  of: number;
  competitors: number;
  /** cents/L, positive = you are dearer than them. */
  vsCheapestCents: number;
  vsAverageCents: number;
  alert: "undercut" | "below-average" | null;
}

const cents = (perL: number) => Math.round(perL * 10000) / 100;

/**
 * Flatten price files into one observation per station for a single grade,
 * newest first-hand reading wins. A file written before `observedAt` existed
 * falls back to its own `recordedAt` — the best honest upper bound we have.
 * Stations that never posted this grade simply do not appear.
 */
export function gradeObservations(
  files: Array<CompetitorPricesFile | undefined>,
  gradeId: string,
): Observation[] {
  const newest = new Map<string, Observation>();
  for (const file of files) {
    if (!file) continue;
    for (const e of file.entries ?? []) {
      if (e.gradeId !== gradeId || !(e.pumpPricePerL > 0)) continue;
      const observedAt = e.observedAt ?? file.recordedAt;
      const prev = newest.get(e.competitorId);
      if (prev && (prev.observedAt ?? "") >= (observedAt ?? "")) continue;
      newest.set(e.competitorId, { competitorId: e.competitorId, pricePerL: e.pumpPricePerL, observedAt });
    }
  }
  return [...newest.values()];
}

/** Observations read within FRESH_WINDOW_MS. Undated ones cannot qualify. */
export function freshObservations(obs: Observation[], now = Date.now()): Observation[] {
  return obs.filter((o) => {
    if (!(o.pricePerL > 0)) return false;
    const t = o.observedAt ? Date.parse(o.observedAt) : NaN;
    return Number.isFinite(t) && now - t < FRESH_WINDOW_MS;
  });
}

/**
 * Your standing among the stations seen in the last 24h, or null when there is
 * nothing recent to stand against — callers render "not enough recent data"
 * rather than a confident-looking rank of one.
 */
export function marketPosition(
  yourPerL: number,
  obs: Observation[],
  now = Date.now(),
): MarketPosition | null {
  if (!(yourPerL > 0)) return null;
  const fresh = freshObservations(obs, now);
  if (fresh.length === 0) return null;

  const prices = fresh.map((o) => o.pricePerL);
  const cheapestPerL = Math.min(...prices);
  const averagePerL = prices.reduce((s, p) => s + p, 0) / prices.length;
  const vsCheapestCents = cents(yourPerL - cheapestPerL);
  const vsAverageCents = cents(yourPerL - averagePerL);

  return {
    yourPerL,
    cheapestPerL,
    averagePerL,
    // Competition ranking: ties share the better rank (two cheapest → both 1st).
    rank: 1 + prices.filter((p) => p < yourPerL).length,
    of: prices.length + 1,
    competitors: prices.length,
    vsCheapestCents,
    vsAverageCents,
    // Being undercut is the louder problem, so it wins when both would fire.
    alert:
      vsCheapestCents >= UNDERCUT_CENTS
        ? "undercut"
        : vsAverageCents <= -BELOW_AVERAGE_CENTS
          ? "below-average"
          : null,
  };
}

