/**
 * Shared ECharts theme tokens that line up with the Tailwind palette in index.css.
 * Resolved at runtime so they follow dark/light mode automatically.
 */
function cssVar(name: string): string {
  if (typeof window === "undefined") return "";
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
}

export function hslVar(name: string, alpha = 1): string {
  const v = cssVar(name);
  if (!v) return "rgba(0,0,0,0)";
  return alpha === 1 ? `hsl(${v})` : `hsla(${v} / ${alpha})`;
}

export const fuelGradeColors: Record<string, string> = {
  regular: "#14b8a6",
  premium: "#f97316",
  diesel: "#a855f7",
  mid: "#0ea5e9",
};

export function colorForGrade(id: string, fallback?: string): string {
  return fuelGradeColors[id.toLowerCase()] ?? fallback ?? "#64748b";
}

/** Competitor stations have no meaningful colour of their own — cycle a palette. */
const competitorPalette = ["#38bdf8", "#f472b6", "#facc15", "#4ade80", "#c084fc", "#fb923c"];

export function colorForCompetitor(index: number, override?: string): string {
  return override ?? competitorPalette[index % competitorPalette.length];
}

