import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { useQueries, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { AlertTriangle, Check, MapPin, Plus, Save, Trash2 } from "lucide-react";

import { api } from "@/lib/api";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { CompetitorDiscovery } from "@/components/CompetitorDiscovery";
import { EChart } from "@/charts/EChart";
import { chartGrid, colorForCompetitor, colorForGrade, tooltipStyle } from "@/charts/theme";
import { isoDate, formatPerLiter } from "@/lib/utils";
import {
  centsToPerL,
  isTracked,
  observedAgo,
  perLToCents,
} from "@/lib/competitor-prices";
import {
  gradeObservations,
  marketPosition,
  statcanGeoLabel,
  type MarketPosition,
} from "@/lib/competitor-stats";
import type {
  CompetitorPriceEntry,
  CompetitorPricesFile,
  CompetitorsConfig,
  DerivedMarginFile,
  FuelGradesConfig,
  GasPricesFile,
  StoreConfig,
  TaxConstants,
} from "@/lib/types";
import { useAuth } from "@/lib/auth-store";

function lastNDates(n: number): string[] {
  const out: string[] = [];
  for (let i = n - 1; i >= 0; i--) {
    const d = new Date();
    d.setDate(d.getDate() - i);
    out.push(isoDate(d));
  }
  return out;
}

export default function FuelPage() {
  const user = useAuth((s) => s.user)!;
  const qc = useQueryClient();
  const today = isoDate();
  const dates = lastNDates(30);

  const gradesQ = useQuery({
    queryKey: ["config", "fuel_grades"],
    queryFn: () => api.readData<FuelGradesConfig>("config/fuel_grades.json"),
  });
  const todayPricesQ = useQuery({
    queryKey: ["gas_prices", today],
    queryFn: () => api.readData<GasPricesFile>(`gas_prices/${today}.json`),
  });
  const marginQs = useQueries({
    queries: dates.map((d) => ({
      queryKey: ["margin", d],
      queryFn: () => api.readData<DerivedMarginFile>(`derived/margin/${d}.json`),
    })),
  });
  const taxesQ = useQuery({
    queryKey: ["config", "taxes"],
    queryFn: () => api.readData<TaxConstants>("config/taxes.json"),
  });
  const storeQ = useQuery({
    queryKey: ["config", "store"],
    queryFn: () => api.readData<StoreConfig>("config/store.json"),
  });
  const competitorsQ = useQuery({
    queryKey: ["config", "competitors"],
    queryFn: () => api.readData<CompetitorsConfig>("config/competitors.json"),
  });
  const competitorPricesQ = useQuery({
    queryKey: ["competitors", today],
    queryFn: () => api.readData<CompetitorPricesFile>(`competitors/${today}.json`),
  });
  const competitorPricesHistoryQs = useQueries({
    queries: dates.map((d) => ({
      queryKey: ["competitors", d],
      queryFn: () => api.readData<CompetitorPricesFile>(`competitors/${d}.json`),
    })),
  });
  const store = storeQ.data?.data;
  const benchmarkQ = useQuery({
    queryKey: ["regional-prices", store?.statcanGeo],
    queryFn: () => api.regionalPrices(String(store?.statcanGeo)),
    enabled: store?.statcanGeo != null,
    retry: false,
    staleTime: 12 * 60 * 60 * 1000, // StatCan publishes monthly; the worker caches too.
  });
  const grades = gradesQ.data?.data?.grades ?? [];
  const competitors = competitorsQ.data?.data?.competitors ?? [];
  const taxes = taxesQ.data?.data;
  // Most recent margin snapshot per grade (for cost + fallback pump price)
  const latestMargin = (() => {
    for (let i = marginQs.length - 1; i >= 0; i--) {
      const d = marginQs[i].data?.data;
      if (d) return d;
    }
    return undefined;
  })();

  const [prices, setPrices] = useState<Record<string, number>>({});
  const [saving, setSaving] = useState(false);
  // Capture is in CENTS -- what's on the roadside sign (152.9), converted on save.
  const [compCents, setCompCents] = useState<Record<string, number>>({}); // key: competitorId|gradeId
  // Stations the human actually looked at this round. Only these get a fresh
  // observedAt; everything else keeps the timestamp it already had.
  const [confirmed, setConfirmed] = useState<Record<string, boolean>>({});
  const [savingCompetitors, setSavingCompetitors] = useState(false);
  const [newCompetitor, setNewCompetitor] = useState("");
  const [editingCompetitors, setEditingCompetitors] = useState(false);
  const [historyGrade, setHistoryGrade] = useState("");

  const trackedCompetitors = competitors.filter(isTracked);
  const readyCount = trackedCompetitors.filter((c) => confirmed[c.id]).length;

  // Today's observations, plus the last price seen for each station in the
  // 30-day window. The latter is only ever a prefill -- it is never saved as if
  // it had been observed today.
  const todayEntries = new Map<string, CompetitorPriceEntry>();
  for (const e of competitorPricesQ.data?.data?.entries ?? []) {
    todayEntries.set(`${e.competitorId}|${e.gradeId}`, e);
  }
  const lastKnownCents: Record<string, number> = {};
  for (let i = 0; i < dates.length; i++) {
    const file = competitorPricesHistoryQs[i].data?.data;
    for (const e of file?.entries ?? []) {
      lastKnownCents[`${e.competitorId}|${e.gradeId}`] = perLToCents(e.pumpPricePerL);
    }
  }
  /** Input value: what you typed > what's saved for today > last time we saw it. */
  function centsFor(competitorId: string, gradeId: string): number {
    const key = `${competitorId}|${gradeId}`;
    if (key in compCents) return compCents[key];
    const todays = todayEntries.get(key);
    if (todays) return perLToCents(todays.pumpPricePerL);
    return lastKnownCents[key] ?? 0;
  }
  /** Does today's file already hold a reading for this station? */
  function capturedToday(competitorId: string): boolean {
    return grades.some((g) => todayEntries.has(`${competitorId}|${g.id}`));
  }
  /** When this station's sign was last actually read (today's file only). */
  function observedAtFor(competitorId: string): string | undefined {
    let latest: string | undefined;
    for (const g of grades) {
      const at = todayEntries.get(`${competitorId}|${g.id}`)?.observedAt;
      if (at && (!latest || at > latest)) latest = at;
    }
    // Entries written before observedAt existed: the file's own timestamp is the
    // best honest upper bound on when it was seen.
    if (!latest && capturedToday(competitorId)) latest = competitorPricesQ.data?.data?.recordedAt;
    return latest;
  }

  async function saveCompetitorPrices() {
    setSavingCompetitors(true);
    try {
      const now = new Date().toISOString();
      const entries: CompetitorPriceEntry[] = [];
      for (const c of competitors) {
        if (confirmed[c.id]) {
          for (const g of grades) {
            const cents = centsFor(c.id, g.id);
            if (cents > 0) {
              entries.push({
                competitorId: c.id,
                gradeId: g.id,
                pumpPricePerL: centsToPerL(cents),
                observedAt: now,
                observedBy: user.username,
              });
            }
          }
        } else {
          // Not looked at this round -- carry today's entry over untouched so its
          // original timestamp (and staleness) survives the save.
          for (const g of grades) {
            const e = todayEntries.get(`${c.id}|${g.id}`);
            if (e) entries.push(e);
          }
        }
      }
      const payload: CompetitorPricesFile = {
        date: today,
        entries,
        recordedBy: user.username,
        recordedAt: new Date().toISOString(),
      };
      await api.writeData(
        `competitors/${today}.json`,
        payload,
        competitorPricesQ.data?.sha ?? null,
        `competitor prices ${today}`,
      );
      toast.success("Competitor prices saved");
      setCompCents({});
      setConfirmed({});
      qc.invalidateQueries({ queryKey: ["competitors"] });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to save");
    } finally {
      setSavingCompetitors(false);
    }
  }

  async function saveCompetitorList(next: CompetitorsConfig) {
    try {
      await api.writeData(
        "config/competitors.json",
        next,
        competitorsQ.data?.sha ?? null,
        "update competitors list",
      );
      toast.success("Competitor list updated");
      qc.invalidateQueries({ queryKey: ["config", "competitors"] });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to save");
    }
  }

  useEffect(() => {
    if (todayPricesQ.data?.exists && todayPricesQ.data.data) {
      const m: Record<string, number> = {};
      for (const p of todayPricesQ.data.data.prices) m[p.gradeId] = p.pumpPricePerL;
      setPrices(m);
    } else if (grades.length) {
      setPrices((p) => {
        const next = { ...p };
        for (const g of grades) if (!(g.id in next)) next[g.id] = 0;
        return next;
      });
    }
  }, [todayPricesQ.data?.exists, todayPricesQ.data?.data, grades.length]); // eslint-disable-line react-hooks/exhaustive-deps

  async function savePrices() {
    setSaving(true);
    try {
      const payload: GasPricesFile = {
        date: today,
        prices: grades.map((g) => ({ gradeId: g.id, pumpPricePerL: prices[g.id] ?? 0 })),
        setBy: user.username,
        setAt: new Date().toISOString(),
      };
      await api.writeData(
        `gas_prices/${today}.json`,
        payload,
        todayPricesQ.data?.sha ?? null,
        `gas prices for ${today}`,
      );
      toast.success("Pump prices saved");
      qc.invalidateQueries({ queryKey: ["gas_prices"] });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to save");
    } finally {
      setSaving(false);
    }
  }

  // Per-grade competitor average pump price across all configured competitors
  const competitorAvgByGrade: Record<string, Array<number | null>> = {};
  for (const g of grades) {
    competitorAvgByGrade[g.id] = dates.map((_, i) => {
      const file = competitorPricesHistoryQs[i].data?.data;
      const entries = file?.entries.filter((e) => e.gradeId === g.id) ?? [];
      if (entries.length === 0) return null;
      const sum = entries.reduce((s, e) => s + e.pumpPricePerL, 0);
      return Number((sum / entries.length).toFixed(4));
    });
  }

  // ---------------- Market position ----------------
  /** Today's typed price if there is one, else the last observed pump price. */
  function yourPricePerL(gradeId: string): number {
    const live = prices[gradeId];
    if (live && live > 0) return live;
    return latestMargin?.rows.find((r) => r.gradeId === gradeId)?.avgPumpPrice ?? 0;
  }
  // 24h of freshness can only ever span today + yesterday's file.
  const recentCompetitorFiles = competitorPricesHistoryQs
    .slice(-2)
    .map((q) => q.data?.data);
  const positions = new Map<string, MarketPosition | null>(
    grades.map((g) => [
      g.id,
      marketPosition(yourPricePerL(g.id), gradeObservations(recentCompetitorFiles, g.id)),
    ]),
  );
  const alerts = grades
    .map((g) => ({ grade: g, pos: positions.get(g.id) }))
    .filter((a): a is { grade: (typeof grades)[number]; pos: MarketPosition } => !!a.pos?.alert);

  // ---------------- Per-competitor price history ----------------
  const shownGrade = grades.some((g) => g.id === historyGrade) ? historyGrade : grades[0]?.id ?? "";
  const competitorHistoryOption = {
    grid: chartGrid,
    tooltip: tooltipStyle,
    legend: { textStyle: { color: "#94a3b8" }, top: 4, type: "scroll" },
    xAxis: { type: "category", data: dates.map((d) => d.slice(5)) },
    yAxis: {
      type: "value",
      scale: true,
      axisLabel: { formatter: (v: number) => `$${v.toFixed(2)}` },
      splitLine: { lineStyle: { color: "rgba(148,163,184,0.15)" } },
    },
    series: [
      {
        name: "You",
        type: "line",
        connectNulls: true,
        showSymbol: false,
        lineStyle: { width: 2.4 },
        itemStyle: { color: colorForGrade(shownGrade) },
        data: dates.map((_, i) => {
          const row = marginQs[i].data?.data?.rows.find((r) => r.gradeId === shownGrade);
          return row?.avgPumpPrice ? Number(row.avgPumpPrice.toFixed(4)) : null;
        }),
      },
      ...trackedCompetitors.map((c, idx) => ({
        name: c.name,
        type: "line",
        // Sign readings are occasional, not daily — join across the gaps rather
        // than drawing a dozen disconnected dots.
        connectNulls: true,
        showSymbol: true,
        symbolSize: 5,
        lineStyle: { width: 1.4, type: "dashed" },
        itemStyle: { color: colorForCompetitor(idx, c.color) },
        data: dates.map((_, i) => {
          const e = competitorPricesHistoryQs[i].data?.data?.entries.find(
            (x) => x.competitorId === c.id && x.gradeId === shownGrade,
          );
          return e?.pumpPricePerL ? Number(e.pumpPricePerL.toFixed(4)) : null;
        }),
      })),
    ],
  };

  const benchmark = benchmarkQ.data;
  const benchmarkMonth = benchmark
    ? new Date(`${benchmark.month}-01T12:00:00Z`).toLocaleDateString("en-CA", {
        month: "long",
        year: "numeric",
        timeZone: "UTC",
      })
    : "";

  const priceVsCostOption = {
    grid: chartGrid,
    tooltip: tooltipStyle,
    legend: { textStyle: { color: "#94a3b8" }, top: 4 },
    xAxis: { type: "category", data: dates.map((d) => d.slice(5)) },
    yAxis: {
      type: "value",
      axisLabel: { formatter: (v: number) => `$${v.toFixed(2)}` },
      splitLine: { lineStyle: { color: "rgba(148,163,184,0.15)" } },
    },
    series: grades.flatMap((g) => {
      const c = colorForGrade(g.id, g.color);
      const competitorSeries =
        competitorAvgByGrade[g.id].some((v) => v != null)
          ? [
              {
                name: `${g.label} competitor`,
                type: "line",
                smooth: true,
                showSymbol: false,
                lineStyle: { width: 1, type: "dotted", opacity: 0.85 },
                itemStyle: { color: c },
                data: competitorAvgByGrade[g.id],
              },
            ]
          : [];
      return [
        {
          name: `${g.label} pump`,
          type: "line",
          smooth: true,
          showSymbol: false,
          lineStyle: { width: 2 },
          itemStyle: { color: c },
          data: dates.map((_, i) => {
            const row = marginQs[i].data?.data?.rows.find((r) => r.gradeId === g.id);
            return row?.avgPumpPrice ? Number(row.avgPumpPrice.toFixed(4)) : null;
          }),
        },
        {
          name: `${g.label} cost`,
          type: "line",
          smooth: true,
          showSymbol: false,
          lineStyle: { width: 1.5, type: "dashed" },
          itemStyle: { color: c },
          data: dates.map((_, i) => {
            const row = marginQs[i].data?.data?.rows.find((r) => r.gradeId === g.id);
            return row?.rollingAvgCost ? Number(row.rollingAvgCost.toFixed(4)) : null;
          }),
        },
        ...competitorSeries,
      ];
    }),
  };

  return (
    <div className="space-y-8">
      <header>
        <h1 className="text-3xl font-semibold tracking-tight">Fuel</h1>
        <p className="text-sm text-muted-foreground">
          Daily pump price, current rolling-average cost, and recent trends.
        </p>
      </header>

      {grades.length === 0 && !gradesQ.isLoading ? (
        <div className="flex items-start gap-3 rounded-md border border-amber-300/40 bg-amber-50/30 p-4 text-sm dark:border-amber-900/40 dark:bg-amber-950/20">
          <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-amber-600 dark:text-amber-400" />
          <div className="space-y-1">
            <div className="font-medium">No fuel grades configured yet</div>
            <p className="text-muted-foreground">
              Open <Link to="/settings" className="font-medium underline">Settings &rarr; Fuel grades</Link> and click
              <span className="font-medium"> Save grades</span> to seed REGULAR / PREMIUM / DIESEL. The pump price form
              and trend chart below will populate after that.
            </p>
          </div>
        </div>
      ) : null}

      <Card>
        <CardHeader>
          <CardTitle>Today's pump prices</CardTitle>
          <CardDescription>Tax-inclusive retail price per liter -- this is what customers see.</CardDescription>
        </CardHeader>
        <CardContent className="grid gap-4 md:grid-cols-3">
          {grades.map((g) => (
            <div key={g.id} className="space-y-1.5">
              <Label className="text-xs text-muted-foreground">{g.label}</Label>
              <Input
                type="number"
                step="0.001"
                inputMode="decimal"
                value={prices[g.id] || ""}
                onChange={(e) =>
                  setPrices((p) => ({ ...p, [g.id]: parseFloat(e.target.value) || 0 }))
                }
                placeholder="0.000"
              />
              <div className="text-xs text-muted-foreground">{formatPerLiter(prices[g.id] ?? 0)}</div>
            </div>
          ))}
          <div className="md:col-span-3 flex justify-end">
            <Button onClick={savePrices} disabled={saving}>
              <Save className="h-4 w-4" /> Save prices
            </Button>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="flex flex-row items-start justify-between space-y-0">
          <div className="space-y-1">
            <CardTitle>Competitor prices</CardTitle>
            <CardDescription>
              What you saw on their signs, in cents. Human observations — not a live feed.
            </CardDescription>
          </div>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setEditingCompetitors((v) => !v)}
          >
            {editingCompetitors ? "Done editing" : "Edit list"}
          </Button>
        </CardHeader>
        <CardContent className="space-y-4">
          {editingCompetitors || trackedCompetitors.length === 0 ? (
            <CompetitorDiscovery
              store={storeQ.data?.data}
              competitors={competitors}
              onSave={(next) => saveCompetitorList({ competitors: next })}
            />
          ) : null}

          {editingCompetitors ? (
            <div className="space-y-2 rounded-md border bg-card/40 p-3">
              <Label className="text-xs text-muted-foreground">Competitor stations</Label>
              {competitors.length === 0 ? (
                <p className="text-xs text-muted-foreground">
                  No competitors yet. Find them above, or add one by name below.
                </p>
              ) : (
                competitors.map((c) => (
                  <div key={c.id} className="flex items-center gap-2">
                    <input
                      type="checkbox"
                      aria-label={`Track ${c.name}`}
                      checked={isTracked(c)}
                      onChange={(e) =>
                        saveCompetitorList({
                          competitors: competitors.map((cc) =>
                            cc.id === c.id ? { ...cc, tracked: e.target.checked } : cc,
                          ),
                        })
                      }
                      className="h-4 w-4 accent-teal-500"
                    />
                    <span className="min-w-0 flex-1 truncate text-sm">
                      {c.name}
                      {c.street ? (
                        <span className="text-xs text-muted-foreground"> · {c.street}</span>
                      ) : null}
                    </span>
                    {c.distanceKm != null ? (
                      <span className="number-tabular shrink-0 text-xs text-muted-foreground">
                        {c.distanceKm.toFixed(1)} km
                      </span>
                    ) : null}
                    <Button
                      variant="ghost"
                      size="icon"
                      aria-label={`Remove ${c.name}`}
                      onClick={() =>
                        saveCompetitorList({
                          competitors: competitors.filter((cc) => cc.id !== c.id),
                        })
                      }
                    >
                      <Trash2 className="h-3.5 w-3.5" />
                    </Button>
                  </div>
                ))
              )}
              <div className="flex items-center gap-2 pt-2">
                <Input
                  value={newCompetitor}
                  placeholder="e.g. Petro-Canada down the road"
                  onChange={(e) => setNewCompetitor(e.target.value)}
                />
                <Button
                  size="sm"
                  disabled={!newCompetitor.trim()}
                  onClick={() => {
                    const id = newCompetitor
                      .toLowerCase()
                      .replace(/[^a-z0-9]+/g, "-")
                      .replace(/^-|-$/g, "")
                      .slice(0, 32) ||
                      `c${competitors.length + 1}`;
                    if (competitors.some((c) => c.id === id)) return;
                    saveCompetitorList({
                      competitors: [...competitors, { id, name: newCompetitor.trim() }],
                    });
                    setNewCompetitor("");
                  }}
                >
                  <Plus className="h-4 w-4" /> Add
                </Button>
              </div>
            </div>
          ) : null}

          {trackedCompetitors.length === 0 ? (
            <p className="text-sm text-muted-foreground">
              No stations tracked yet. Find them above, or use <b>Edit list</b> to add one by name.
            </p>
          ) : (
            <>
              <div className="space-y-2">
                {trackedCompetitors.map((c) => {
                  const seen = observedAgo(observedAtFor(c.id));
                  const ready = !!confirmed[c.id];
                  // Nothing seen today and not confirmed => the numbers showing are
                  // last-seen prefills, so they are dimmed rather than presented as today's.
                  const prefillOnly = !ready && !capturedToday(c.id);
                  return (
                    <div
                      key={c.id}
                      className={`space-y-2 rounded-lg border p-3 ${
                        ready ? "border-primary/50 bg-primary/5" : ""
                      }`}
                    >
                      <div className="flex items-center gap-2">
                        <div className="min-w-0 flex-1">
                          <div className="truncate text-sm font-medium">{c.name}</div>
                          <div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
                            {c.distanceKm != null ? (
                              <span className="number-tabular">
                                <MapPin className="mr-0.5 inline h-3 w-3" />
                                {c.distanceKm.toFixed(1)} km
                              </span>
                            ) : null}
                            {seen ? (
                              seen.stale ? (
                                <Badge variant="warning">stale &middot; seen {seen.label}</Badge>
                              ) : (
                                <span>seen {seen.label}</span>
                              )
                            ) : (
                              <span>not seen today</span>
                            )}
                          </div>
                        </div>
                        <Button
                          size="sm"
                          variant={ready ? "default" : "outline"}
                          aria-pressed={ready}
                          onClick={() => setConfirmed((p) => ({ ...p, [c.id]: !p[c.id] }))}
                        >
                          <Check className="h-4 w-4" /> {ready ? "Ready" : "Same"}
                        </Button>
                      </div>
                      <div className="grid grid-cols-3 gap-2">
                        {grades.map((g) => {
                          const key = `${c.id}|${g.id}`;
                          const theirCents = centsFor(c.id, g.id);
                          const yourCents = perLToCents(prices[g.id] || 0);
                          const diff =
                            theirCents > 0 && yourCents > 0 ? theirCents - yourCents : 0;
                          return (
                            <div key={g.id} className="space-y-1">
                              <Label className="text-[10px] uppercase text-muted-foreground">
                                {g.label}
                              </Label>
                              <Input
                                type="number"
                                step="0.1"
                                inputMode="decimal"
                                aria-label={`${c.name} ${g.label} price in cents per liter`}
                                value={theirCents || ""}
                                placeholder="152.9"
                                onChange={(e) => {
                                  const v = parseFloat(e.target.value) || 0;
                                  setCompCents((p) => ({ ...p, [key]: v }));
                                  setConfirmed((p) => ({ ...p, [c.id]: true }));
                                }}
                                className={`h-10 text-right number-tabular ${
                                  prefillOnly ? "opacity-60" : ""
                                }`}
                              />
                              {diff !== 0 ? (
                                <div
                                  className={`mt-0.5 text-right text-[10px] number-tabular ${
                                    diff > 0
                                      ? "text-emerald-600 dark:text-emerald-400"
                                      : "text-rose-600 dark:text-rose-400"
                                  }`}
                                >
                                  {diff > 0 ? "+" : ""}
                                  {diff.toFixed(1)}c
                                </div>
                              ) : null}
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  );
                })}
              </div>
              <div className="flex flex-wrap items-center justify-between gap-2">
                <p className="text-xs text-muted-foreground">
                  Cents, as on the sign (152.9). Values are last-seen prefills — tap{" "}
                  <b>Same</b> if the sign hasn't changed, or type the new one.
                </p>
                <Button
                  onClick={saveCompetitorPrices}
                  disabled={savingCompetitors || readyCount === 0}
                >
                  <Save className="h-4 w-4" />
                  Save {readyCount > 0 ? `${readyCount} station${readyCount > 1 ? "s" : ""}` : ""}
                </Button>
              </div>
            </>
          )}
        </CardContent>
      </Card>

      {alerts.length > 0 ? (
        <div className="animate-fade-in flex items-start gap-3 rounded-xl border border-amber-400/40 bg-amber-50/40 p-4 text-sm dark:bg-amber-950/20">
          <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-amber-600 dark:text-amber-400" />
          <div className="space-y-1">
            <div className="font-medium text-amber-700 dark:text-amber-300">
              {alerts.some((a) => a.pos.alert === "undercut")
                ? "You are being undercut nearby"
                : "You may be leaving margin on the table"}
            </div>
            <div className="space-y-0.5 text-muted-foreground">
              {alerts.map(({ grade, pos }) => (
                <p key={grade.id} className="number-tabular">
                  {grade.label}:{" "}
                  {pos.alert === "undercut"
                    ? `${pos.vsCheapestCents.toFixed(1)}c above the cheapest of ${pos.competitors} nearby — volume risk.`
                    : `${Math.abs(pos.vsAverageCents).toFixed(1)}c below the average of ${pos.competitors} nearby — room to move up.`}
                </p>
              ))}
            </div>
          </div>
        </div>
      ) : null}

      <Card>
        <CardHeader>
          <CardTitle>Market position</CardTitle>
          <CardDescription>
            Where your sign sits against stations read in the last 24 hours. Older readings are
            not counted.
          </CardDescription>
        </CardHeader>
        <CardContent className="grid gap-4 md:grid-cols-3">
          {grades.map((g) => {
            const pos = positions.get(g.id) ?? null;
            return (
              <div key={g.id} className="space-y-2 rounded-lg border p-3">
                <div className="flex items-baseline justify-between">
                  <span className="text-sm font-medium">{g.label}</span>
                  <span className="number-tabular text-sm text-muted-foreground">
                    {yourPricePerL(g.id) > 0
                      ? `${perLToCents(yourPricePerL(g.id)).toFixed(1)}c`
                      : "--"}
                  </span>
                </div>
                {!pos ? (
                  <p className="text-xs text-muted-foreground">
                    Not enough recent data.{" "}
                    {yourPricePerL(g.id) > 0
                      ? "No competitor sign read in the last 24h."
                      : "Set today's pump price above."}
                  </p>
                ) : (
                  <>
                    <div className="number-tabular text-sm">
                      {ordinal(pos.rank)} of {pos.of}
                      <span
                        className={
                          pos.vsCheapestCents > 0
                            ? " text-rose-600 dark:text-rose-400"
                            : " text-emerald-600 dark:text-emerald-400"
                        }
                      >
                        {" "}
                        &middot; {pos.vsCheapestCents > 0 ? "+" : ""}
                        {pos.vsCheapestCents.toFixed(1)}c vs cheapest
                      </span>
                    </div>
                    <dl className="grid grid-cols-2 gap-x-2 text-xs text-muted-foreground">
                      <dt>Cheapest nearby</dt>
                      <dd className="number-tabular text-right">
                        {perLToCents(pos.cheapestPerL).toFixed(1)}c
                      </dd>
                      <dt>Average nearby</dt>
                      <dd className="number-tabular text-right">
                        {perLToCents(pos.averagePerL).toFixed(1)}c
                      </dd>
                    </dl>
                    <p className="text-[11px] text-muted-foreground">
                      {pos.competitors} station{pos.competitors === 1 ? "" : "s"} seen in the last
                      24h
                    </p>
                  </>
                )}
              </div>
            );
          })}
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="flex flex-row items-start justify-between space-y-0">
          <div className="space-y-1">
            <CardTitle>Competitor price history</CardTitle>
            <CardDescription>
              One line per tracked station, 30 days. Gaps are days nobody read the sign.
            </CardDescription>
          </div>
          <div className="flex gap-1">
            {grades.map((g) => (
              <Button
                key={g.id}
                size="sm"
                variant={g.id === shownGrade ? "default" : "ghost"}
                aria-pressed={g.id === shownGrade}
                onClick={() => setHistoryGrade(g.id)}
              >
                {g.label}
              </Button>
            ))}
          </div>
        </CardHeader>
        <CardContent>
          {trackedCompetitors.length === 0 ? (
            <p className="text-sm text-muted-foreground">
              No tracked stations yet — find them in the card above.
            </p>
          ) : (
            <EChart option={competitorHistoryOption} height={300} />
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Regional benchmark</CardTitle>
          <CardDescription>
            {store?.statcanGeo == null
              ? "Statistics Canada monthly average — pick your region to switch it on."
              : benchmark
                ? `${statcanGeoLabel(store.statcanGeo) ?? `Geography ${store.statcanGeo}`} · ${benchmarkMonth} — monthly average, not live.`
                : `${statcanGeoLabel(store.statcanGeo) ?? `Geography ${store.statcanGeo}`} — monthly average, not live.`}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {store?.statcanGeo == null ? (
            <p className="text-sm text-muted-foreground">
              Choose a benchmark city in{" "}
              <Link to="/settings" className="font-medium underline">
                Settings &rarr; Store
              </Link>
              . Canada-wide is available but publishes regular only.
            </p>
          ) : benchmarkQ.isLoading ? (
            <p className="text-sm text-muted-foreground">Loading the Statistics Canada average…</p>
          ) : benchmarkQ.isError || !benchmark ? (
            <p className="text-sm text-rose-600 dark:text-rose-400" role="alert">
              {benchmarkQ.error instanceof Error
                ? benchmarkQ.error.message
                : "Could not load the regional benchmark."}
            </p>
          ) : (
            <table className="w-full text-sm">
              <thead>
                <tr className="text-xs text-muted-foreground">
                  <th className="py-1 text-left font-normal">Grade</th>
                  <th className="py-1 text-right font-normal">Yours</th>
                  <th className="py-1 text-right font-normal">{benchmarkMonth} avg</th>
                  <th className="py-1 text-right font-normal">Difference</th>
                </tr>
              </thead>
              <tbody>
                {grades.map((g) => {
                  const regional = benchmark.pricesCentsPerL[g.id];
                  const published = typeof regional === "number" && Number.isFinite(regional);
                  const yours = perLToCents(yourPricePerL(g.id));
                  const diff = published && yours > 0 ? yours - regional : null;
                  return (
                    <tr key={g.id} className="border-t">
                      <td className="py-1.5">{g.label}</td>
                      <td className="number-tabular py-1.5 text-right">
                        {yours > 0 ? `${yours.toFixed(1)}c` : "--"}
                      </td>
                      <td className="number-tabular py-1.5 text-right">
                        {published ? (
                          `${regional.toFixed(1)}c`
                        ) : (
                          <span className="text-xs text-muted-foreground">not published here</span>
                        )}
                      </td>
                      <td
                        className={`number-tabular py-1.5 text-right ${
                          diff == null
                            ? "text-muted-foreground"
                            : diff > 0
                              ? "text-rose-600 dark:text-rose-400"
                              : "text-emerald-600 dark:text-emerald-400"
                        }`}
                      >
                        {diff == null ? "--" : `${diff > 0 ? "+" : ""}${diff.toFixed(1)}c`}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Pump price vs rolling-avg cost</CardTitle>
          <CardDescription>
            Dashed = cost. Solid = pump price. Dotted thin = competitor average.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <EChart option={priceVsCostOption} height={320} />
        </CardContent>
      </Card>

      <section className="grid gap-4 lg:grid-cols-3">
        {grades.map((g) => (
          <Card key={g.id}>
            <CardHeader>
              <CardTitle className="flex items-center justify-between">
                <span>{g.label} spread</span>
                <span className="text-xs font-normal text-muted-foreground">net sell - cost</span>
              </CardTitle>
              <CardDescription>
                Green above zero = profit. Red below = loss. 30-day daily margin.
              </CardDescription>
            </CardHeader>
            <CardContent>
              <EChart
                option={spreadOption(
                  dates,
                  dates.map((_, i) => {
                    const row = marginQs[i].data?.data?.rows.find((r) => r.gradeId === g.id);
                    return row?.hasSales ? Number(row.associateMargin.toFixed(4)) : null;
                  }),
                )}
                height={200}
              />
            </CardContent>
          </Card>
        ))}
      </section>

      <section className="grid gap-4 lg:grid-cols-3">
        {grades.map((g) => {
          const row = latestMargin?.rows.find((r) => r.gradeId === g.id);
          const livePump = prices[g.id];
          const pump = (livePump && livePump > 0) ? livePump : row?.avgPumpPrice ?? 0;
          const cost = row?.rollingAvgCost ?? 0;
          return (
            <Card key={g.id}>
              <CardHeader>
                <CardTitle className="flex items-center justify-between">
                  <span>{g.label} waterfall</span>
                  <span className="number-tabular text-sm font-normal text-muted-foreground">
                    ${pump.toFixed(4)}/L pump
                  </span>
                </CardTitle>
                <CardDescription>
                  Pump price &rarr; net sell (after taxes) &rarr; margin (after cost).
                </CardDescription>
              </CardHeader>
              <CardContent>
                <EChart option={waterfallOption(pump, cost, taxes)} height={260} />
              </CardContent>
            </Card>
          );
        })}
      </section>
    </div>
  );
}

function ordinal(n: number): string {
  const rem100 = n % 100;
  if (rem100 >= 11 && rem100 <= 13) return `${n}th`;
  return `${n}${["th", "st", "nd", "rd"][n % 10] ?? "th"}`;
}

function spreadOption(dates: string[], series: Array<number | null>) {
  const values = series.filter((v): v is number => v != null);
  const maxAbs = values.length > 0 ? Math.max(...values.map((v) => Math.abs(v))) : 0.1;
  return {
    grid: { left: 30, right: 8, top: 12, bottom: 24 },
    tooltip: {
      ...tooltipStyle,
      trigger: "axis",
      formatter: (params: Array<{ axisValueLabel: string; data: number }>) => {
        const p = params[0];
        if (!p || p.data == null) return "";
        const v = p.data;
        return `${p.axisValueLabel}<br/><b>${v >= 0 ? "+" : ""}${(v * 100).toFixed(2)}c/L</b>`;
      },
    },
    xAxis: {
      type: "category",
      data: dates.map((d) => d.slice(5)),
      boundaryGap: false,
      axisLabel: { color: "#94a3b8", fontSize: 10 },
    },
    yAxis: {
      type: "value",
      min: -maxAbs * 1.1 || -0.1,
      max: maxAbs * 1.1 || 0.1,
      axisLabel: {
        formatter: (v: number) => `${(v * 100).toFixed(0)}c`,
        color: "#94a3b8",
        fontSize: 10,
      },
      splitLine: { lineStyle: { color: "rgba(148,163,184,0.12)" } },
    },
    visualMap: [
      {
        show: false,
        type: "piecewise",
        seriesIndex: 0,
        pieces: [
          { lt: 0, color: "#f43f5e" },
          { gte: 0, color: "#10b981" },
        ],
      },
    ],
    series: [
      {
        type: "line",
        smooth: true,
        showSymbol: false,
        sampling: "lttb",
        lineStyle: { width: 1.8 },
        areaStyle: { origin: "start", opacity: 0.25 },
        markLine: {
          silent: true,
          symbol: "none",
          lineStyle: { color: "rgba(148,163,184,0.5)", type: "dashed" },
          data: [{ yAxis: 0 }],
        },
        data: series,
      },
    ],
  };
}

interface WaterfallStep {
  label: string;
  delta: number;
  kind: "start" | "decrease" | "increase" | "subtotal" | "result";
}

function buildWaterfallSteps(
  pumpPricePerL: number,
  rollingAvgCost: number,
  taxes: TaxConstants | undefined,
): WaterfallStep[] {
  if (pumpPricePerL <= 0) return [];
  const fet = taxes?.fetPerL ?? 0;
  const pft = taxes?.pftPerL ?? 0;
  const carbon = taxes?.carbonPerL ?? 0;
  const urban = taxes?.urbanPerL ?? 0;
  const rebate = taxes?.rebatePerL ?? 0;
  const hst = (taxes?.hstPct ?? 0) / 100;
  const gst = (taxes?.gstPct ?? 0) / 100;
  const pst = (taxes?.pstPct ?? 0) / 100;

  // Replicate netSellPricePerL():
  //   div = (1 + HST) if HST > 0 else (1 + GST + PST)
  //   netSell = pump / div - FET - PFT - Carbon - Urban + Rebate
  const div = hst > 0 ? 1 + hst : 1 + gst + pst;
  const afterSalesTax = pumpPricePerL / div;
  const salesTaxDelta = pumpPricePerL - afterSalesTax;

  const steps: WaterfallStep[] = [{ label: "Pump", delta: pumpPricePerL, kind: "start" }];
  if (salesTaxDelta > 0) {
    steps.push({
      label: hst > 0 ? `-HST ${(hst * 100).toFixed(0)}%` : `-GST/PST`,
      delta: -salesTaxDelta,
      kind: "decrease",
    });
  }
  if (fet > 0) steps.push({ label: "-FET", delta: -fet, kind: "decrease" });
  if (pft > 0) steps.push({ label: "-PFT", delta: -pft, kind: "decrease" });
  if (carbon > 0) steps.push({ label: "-Carbon", delta: -carbon, kind: "decrease" });
  if (urban > 0) steps.push({ label: "-Urban", delta: -urban, kind: "decrease" });
  if (rebate > 0) steps.push({ label: "+Rebate", delta: rebate, kind: "increase" });

  const netSell =
    afterSalesTax - fet - pft - carbon - urban + rebate;
  steps.push({ label: "Net sell", delta: netSell, kind: "subtotal" });
  steps.push({ label: "-Cost", delta: -rollingAvgCost, kind: "decrease" });
  steps.push({ label: "Margin", delta: netSell - rollingAvgCost, kind: "result" });

  return steps;
}

function waterfallOption(
  pumpPricePerL: number,
  rollingAvgCost: number,
  taxes: TaxConstants | undefined,
) {
  const steps = buildWaterfallSteps(pumpPricePerL, rollingAvgCost, taxes);
  // Convert steps to ECharts bar data using a placeholder series for floating bars.
  const categories: string[] = [];
  const placeholder: Array<number | string> = [];
  const positives: Array<number | string> = [];
  const negatives: Array<number | string> = [];
  const totals: Array<number | string> = [];

  let running = 0;
  for (const s of steps) {
    categories.push(s.label);
    if (s.kind === "start" || s.kind === "subtotal" || s.kind === "result") {
      placeholder.push(0);
      positives.push("");
      negatives.push("");
      totals.push(Number(s.delta.toFixed(4)));
      running = s.delta;
    } else if (s.delta >= 0) {
      placeholder.push(Number(running.toFixed(4)));
      positives.push(Number(s.delta.toFixed(4)));
      negatives.push("");
      totals.push("");
      running += s.delta;
    } else {
      const next = running + s.delta;
      placeholder.push(Number(next.toFixed(4)));
      positives.push("");
      negatives.push(Number((-s.delta).toFixed(4)));
      totals.push("");
      running = next;
    }
  }

  return {
    grid: chartGrid,
    tooltip: {
      ...tooltipStyle,
      formatter: (params: Array<{ axisValue: string; data: number | string }>) => {
        const real = params.find((p) => p.data !== "" && p.data !== 0);
        if (!real) return "";
        return `${real.axisValue}<br/><b>$${Number(real.data).toFixed(4)}/L</b>`;
      },
    },
    xAxis: {
      type: "category",
      data: categories,
      axisLabel: { color: "#94a3b8", fontSize: 10, interval: 0, rotate: 30 },
    },
    yAxis: {
      type: "value",
      axisLabel: { formatter: (v: number) => `$${v.toFixed(2)}` },
      splitLine: { lineStyle: { color: "rgba(148,163,184,0.15)" } },
    },
    series: [
      {
        name: "placeholder",
        type: "bar",
        stack: "wf",
        itemStyle: { color: "transparent" },
        emphasis: { itemStyle: { color: "transparent" } },
        data: placeholder,
      },
      {
        name: "decrease",
        type: "bar",
        stack: "wf",
        itemStyle: { color: "#f43f5e" },
        data: negatives,
      },
      {
        name: "increase",
        type: "bar",
        stack: "wf",
        itemStyle: { color: "#10b981" },
        data: positives,
      },
      {
        name: "totals",
        type: "bar",
        stack: "wf",
        itemStyle: {
          color: (params: { dataIndex: number; data: number | string }) => {
            const s = steps[params.dataIndex];
            if (s?.kind === "result") {
              const v = typeof params.data === "number" ? params.data : 0;
              return v >= 0 ? "#0ea5e9" : "#f43f5e";
            }
            if (s?.kind === "subtotal") return "#64748b";
            return "#475569";
          },
        },
        data: totals,
      },
    ],
  };
}
