/**
 * Pure OCR-text → ScanResult parser for the on-device (Tesseract) fallback.
 * No DOM, no network. Produces the exact shape POST /api/scan (Gemini) returns
 * so the review-then-apply UI works identically for both engines.
 */
import type { ScanResult } from "./types";

interface NumToken {
  value: number;
  dollar: boolean; // had a $ prefix
  twoDec: boolean; // exactly two decimals — reads as money
  liters: boolean; // had an L / litres suffix
}

// $?1,234.56 / 1234.5 L / 200 — commas optional, suffix optional.
const NUM_RE = /(\$\s*)?(\d{1,3}(?:,\d{3})+(?:\.\d+)?|\d+(?:\.\d+)?)\s*(L(?:itres?|iters?)?\b)?/gi;

function numbersIn(text: string): NumToken[] {
  const out: NumToken[] = [];
  for (const m of text.matchAll(NUM_RE)) {
    const raw = m[2];
    if (!raw) continue;
    const value = Number(raw.replace(/,/g, ""));
    if (!Number.isFinite(value)) continue;
    out.push({
      value,
      dollar: !!m[1],
      twoDec: /\.\d{2}$/.test(raw),
      liters: !!m[3],
    });
  }
  return out;
}

/** Last money-looking number on a line (receipts put the amount at the end). */
function moneyIn(line: string): number | null {
  const nums = numbersIn(line);
  if (nums.length === 0) return null;
  const money = nums.filter((n) => n.dollar || n.twoDec);
  return (money.length > 0 ? money[money.length - 1] : nums[nums.length - 1]).value;
}

/**
 * Case-insensitive fuzzy grade match. Exact substring first; otherwise a
 * startsWith comparison between the label's first word and each line word,
 * to survive common OCR truncation ("REGU" for "REGULAR").
 * Returns the index just past the match, or -1.
 */
function matchGrade(lineU: string, labelU: string): number {
  const i = lineU.indexOf(labelU);
  if (i >= 0) return i + labelU.length;
  const first = labelU.split(/[^A-Z0-9]+/)[0] ?? "";
  if (first.length < 3) return -1;
  for (const word of lineU.split(/[^A-Z0-9]+/)) {
    if (word.length >= 3 && (word.startsWith(first) || first.startsWith(word))) {
      return lineU.indexOf(word) + word.length;
    }
  }
  return -1;
}

type Setter = (r: ScanResult, v: number) => void;

// First matching rule wins; checked in this order so DEBIT/CREDIT beat DEPOSIT.
const KEYWORD_RULES: Array<{ re: RegExp; out?: RegExp; set: Setter; setOut?: Setter }> = [
  { re: /\bDEBIT\b/, set: (r, v) => (r.card.debitCAD ??= v) },
  { re: /\bCREDIT\b/, set: (r, v) => (r.card.creditCAD ??= v) },
  { re: /\bDEPOSIT\b/, set: (r, v) => (r.bankDepositCAD ??= v) },
  { re: /\bFLOAT\b/, set: (r, v) => (r.cashFloatCAD ??= v) },
  {
    re: /LOTT(O|ERY)/,
    out: /OUT|PAYOUT|PAID/,
    set: (r, v) => (r.store.lotteryInCAD ??= v),
    setOut: (r, v) => (r.store.lotteryOutCAD ??= v),
  },
  { re: /TOBACCO|CIGARETTE|\bCIGS?\b/, set: (r, v) => (r.store.tobaccoCAD ??= v) },
  { re: /ALCOHOL|BEER|LCBO/, set: (r, v) => (r.store.alcoholCAD ??= v) },
  { re: /GENERAL|GROCERY|MERCH/, set: (r, v) => (r.store.generalCAD ??= v) },
  { re: /\bOTHER\b/, set: (r, v) => (r.store.otherCAD ??= v) },
];

export function parseReceiptText(text: string, gradeLabels: string[]): ScanResult {
  const result: ScanResult = {
    fuel: gradeLabels.map((label) => ({ gradeLabel: label, salesCAD: null, volumeL: null })),
    store: {
      generalCAD: null,
      tobaccoCAD: null,
      alcoholCAD: null,
      lotteryInCAD: null,
      lotteryOutCAD: null,
      otherCAD: null,
    },
    card: { debitCAD: null, creditCAD: null },
    bankDepositCAD: null,
    cashFloatCAD: null,
    caveats: [],
  };

  const lines = text
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter(Boolean);
  const linesU = lines.map((l) => l.toUpperCase());

  // Fuel rows: grade label followed by numbers → salesCAD + volumeL.
  for (const row of result.fuel) {
    const labelU = row.gradeLabel.toUpperCase();
    for (let i = 0; i < linesU.length; i++) {
      const end = matchGrade(linesU[i], labelU);
      if (end < 0) continue;
      const nums = numbersIn(lines[i].slice(end));
      if (nums.length === 0) continue;
      const litersHit = nums.find((n) => n.liters) ?? null;
      const dollarHit = nums.find((n) => n.dollar && n !== litersHit) ?? null;
      let sales = dollarHit ? dollarHit.value : null;
      let volume = litersHit ? litersHit.value : null;
      const pool = nums.filter((n) => n !== litersHit && n !== dollarHit);
      if (sales == null && volume == null && pool.length >= 2 && pool[0].twoDec !== pool[1].twoDec) {
        // The 2-decimal value reads as dollars, the other as liters.
        sales = (pool[0].twoDec ? pool[0] : pool[1]).value;
        volume = (pool[0].twoDec ? pool[1] : pool[0]).value;
      } else {
        // Ambiguous order → assume sales then liters.
        if (sales == null) sales = pool.shift()?.value ?? null;
        if (volume == null) volume = pool.shift()?.value ?? null;
      }
      row.salesCAD = sales;
      row.volumeL = volume;
      break;
    }
    if (row.salesCAD == null && row.volumeL == null) {
      result.caveats.push(`Fuel grade "${row.gradeLabel}" was not found on the receipt.`);
    }
  }

  // Store / card / deposit / float keyword lines.
  for (let i = 0; i < linesU.length; i++) {
    const rule = KEYWORD_RULES.find((k) => k.re.test(linesU[i]));
    if (!rule) continue;
    const amount = moneyIn(lines[i]);
    if (amount == null) continue;
    if (rule.out && rule.setOut && rule.out.test(linesU[i])) rule.setOut(result, amount);
    else rule.set(result, amount);
  }

  const missing: string[] = [];
  if (result.store.generalCAD == null) missing.push("general store");
  if (result.store.tobaccoCAD == null) missing.push("tobacco");
  if (result.store.alcoholCAD == null) missing.push("alcohol");
  if (result.store.lotteryInCAD == null) missing.push("lottery in");
  if (result.store.lotteryOutCAD == null) missing.push("lottery payout");
  if (result.store.otherCAD == null) missing.push("other");
  if (result.card.debitCAD == null) missing.push("debit");
  if (result.card.creditCAD == null) missing.push("credit");
  if (result.bankDepositCAD == null) missing.push("bank deposit");
  if (result.cashFloatCAD == null) missing.push("cash float");
  if (missing.length > 0) {
    result.caveats.push(`Not found on the receipt: ${missing.join(", ")}.`);
  }

  return result;
}
