/**
 * Find nearby fuel stations from OpenStreetMap (via the worker) and fold the
 * chosen ones into config/competitors.json.
 *
 * OSM gives discovery only — never prices. Prices come from the human capture
 * list on the Fuel page.
 */
import { useState } from "react";
import { Link } from "react-router-dom";
import { Loader2, MapPin, Radar, Save } from "lucide-react";

import { api } from "@/lib/api";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { mergeDiscovered } from "@/lib/competitor-prices";
import type { Competitor, NearbyStation, StoreConfig } from "@/lib/types";

interface Props {
  store: StoreConfig | undefined;
  competitors: Competitor[];
  onSave: (next: Competitor[]) => Promise<void>;
}

export function CompetitorDiscovery({ store, competitors, onSave }: Props) {
  const location = store?.location;
  const radiusKm = store?.competitorRadiusKm ?? 5;
  const [stations, setStations] = useState<NearbyStation[] | null>(null);
  const [selected, setSelected] = useState<Set<number>>(new Set());
  const [searching, setSearching] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function find() {
    if (!location) return;
    setSearching(true);
    setError(null);
    try {
      const res = await api.nearbyStations(location.lat, location.lng, radiusKm);
      setStations(res.stations);
      // Pre-check whatever is already tracked so a re-run never silently drops it.
      setSelected(
        new Set(
          res.stations
            .filter((s) => competitors.some((c) => c.osmId === s.osmId && c.tracked !== false))
            .map((s) => s.osmId),
        ),
      );
    } catch (err) {
      setStations(null);
      setError(err instanceof Error ? err.message : "Station search failed");
    } finally {
      setSearching(false);
    }
  }

  async function save() {
    if (!stations) return;
    setSaving(true);
    try {
      await onSave(mergeDiscovered(competitors, stations, selected));
      setStations(null);
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="space-y-3 rounded-lg border border-border/60 bg-background/30 p-3">
      <div className="flex flex-wrap items-center gap-3">
        <Button variant="outline" size="sm" onClick={find} disabled={!location || searching}>
          {searching ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <Radar className="h-4 w-4" />
          )}
          Find nearby stations
        </Button>
        {location ? (
          <span className="text-xs text-muted-foreground">
            Within {radiusKm} km of your station · OpenStreetMap
          </span>
        ) : (
          <span className="text-xs text-muted-foreground">
            Set your station location in{" "}
            <Link to="/settings" className="font-medium underline">
              Settings &rarr; Store
            </Link>{" "}
            first — the search needs coordinates.
          </span>
        )}
      </div>

      {error ? (
        <p className="text-xs font-medium text-red-600 dark:text-red-400" role="alert">
          {error}
        </p>
      ) : null}

      {stations ? (
        stations.length === 0 ? (
          <p className="text-xs text-muted-foreground">
            No fuel stations found within {radiusKm} km. Widen the radius in Settings &rarr; Store,
            or add one by name below.
          </p>
        ) : (
          <>
            <div className="overflow-hidden rounded-md border">
              {stations.map((s) => {
                const known = competitors.find((c) => c.osmId === s.osmId);
                return (
                  <label
                    key={s.osmId}
                    className="flex cursor-pointer items-center gap-3 border-b px-3 py-2 text-sm last:border-b-0 hover:bg-secondary/50"
                  >
                    <input
                      type="checkbox"
                      checked={selected.has(s.osmId)}
                      onChange={(e) =>
                        setSelected((prev) => {
                          const next = new Set(prev);
                          if (e.target.checked) next.add(s.osmId);
                          else next.delete(s.osmId);
                          return next;
                        })
                      }
                      className="h-4 w-4 accent-teal-500"
                    />
                    <span className="min-w-0 flex-1">
                      <span className="font-medium">{known?.name ?? s.name}</span>
                      {s.brand && s.brand !== s.name ? (
                        <span className="text-muted-foreground"> · {s.brand}</span>
                      ) : null}
                      {s.street ? (
                        <span className="block truncate text-xs text-muted-foreground">
                          {s.street}
                        </span>
                      ) : null}
                    </span>
                    {known ? (
                      <Badge variant="secondary" className="shrink-0">
                        already on the list
                      </Badge>
                    ) : null}
                    <span className="number-tabular shrink-0 text-xs text-muted-foreground">
                      <MapPin className="mr-1 inline h-3 w-3" />
                      {s.distanceKm.toFixed(1)} km
                    </span>
                  </label>
                );
              })}
            </div>
            <div className="flex items-center justify-between gap-2">
              <span className="text-xs text-muted-foreground">
                {selected.size} of {stations.length} selected
              </span>
              <Button size="sm" onClick={save} disabled={saving}>
                {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
                Save list
              </Button>
            </div>
          </>
        )
      ) : null}
    </div>
  );
}
