/**
 * Parse coordinates a user pasted from Google Maps.
 *
 * Right-click a spot in Google Maps → the context menu's first item is
 * "43.653226, -79.383184" → paste. Also accepts a copied map URL. This exists
 * so setting the store location needs no Geocoding API call (and works before
 * any Maps key is configured).
 */
export interface LatLng {
  lat: number;
  lng: number;
}

const DECIMAL_PAIR = /(-?\d{1,3}(?:\.\d+)?)\s*[, ]\s*(-?\d{1,3}(?:\.\d+)?)/;
// google.com/maps/@43.65,-79.38,15z  and  ...!3d43.65!4d-79.38
const URL_AT = /@(-?\d{1,3}(?:\.\d+)?),(-?\d{1,3}(?:\.\d+)?)/;
const URL_3D4D = /!3d(-?\d{1,3}(?:\.\d+)?)!4d(-?\d{1,3}(?:\.\d+)?)/;

function valid(lat: number, lng: number): LatLng | null {
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  if (Math.abs(lat) > 90 || Math.abs(lng) > 180) return null;
  // 0,0 is Null Island — almost certainly a paste error, not a gas station.
  if (lat === 0 && lng === 0) return null;
  return { lat, lng };
}

export function parseLatLng(input: string): LatLng | null {
  const s = (input ?? "").trim();
  if (!s) return null;
  // URL forms first — a maps URL also contains other number pairs (zoom, ids)
  // that the loose decimal matcher would happily grab.
  for (const re of [URL_3D4D, URL_AT]) {
    const m = s.match(re);
    if (m) {
      const hit = valid(Number(m[1]), Number(m[2]));
      if (hit) return hit;
    }
  }
  const m = s.match(DECIMAL_PAIR);
  if (!m) return null;
  return valid(Number(m[1]), Number(m[2]));
}

/** Straight-line km between two points (haversine). Good enough for "how far is that station". */
export function distanceKm(a: LatLng, b: LatLng): number {
  const R = 6371;
  const dLat = ((b.lat - a.lat) * Math.PI) / 180;
  const dLng = ((b.lng - a.lng) * Math.PI) / 180;
  const la1 = (a.lat * Math.PI) / 180;
  const la2 = (b.lat * Math.PI) / 180;
  const h =
    Math.sin(dLat / 2) ** 2 + Math.sin(dLng / 2) ** 2 * Math.cos(la1) * Math.cos(la2);
  return 2 * R * Math.asin(Math.min(1, Math.sqrt(h)));
}
