import { useEffect, useRef } from "react";

import { cn } from "@/lib/utils";

/**
 * RK monogram with the canonical two-act choreography (shared across the
 * whole RK portfolio — reference: devops-tools/js/tools.js):
 *   Act 1 on mount/click — the strokes arrive out of deep space, each from
 *   its own direction; the trajectory swoop streaks in last.
 *   Act 2 — one full 360° revolution, chained off the swoop's arrival
 *   (animationend), and again on hover.
 * Keyframes live in index.css (.rk-mark). Color rides currentColor.
 */
export function RKLogo({ className }: { className?: string }) {
  const ref = useRef<SVGSVGElement>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const spin = () => {
      el.classList.remove("spin");
      void el.getBoundingClientRect();
      el.classList.add("spin");
    };
    const replay = () => {
      el.classList.remove("arrive", "spin");
      void el.getBoundingClientRect();
      el.classList.add("arrive");
    };
    const onAnimEnd = (e: AnimationEvent) => {
      if (e.animationName === "rkSpin") el.classList.remove("spin");
      if (e.animationName === "rkArrive" && (e.target as Element).classList.contains("swoop")) {
        spin();
        el.dataset.autospin = "done";
      }
    };
    el.addEventListener("animationend", onAnimEnd);
    el.dataset.autospin = "scheduled";
    replay();
    const fallback = setTimeout(() => {
      if (el.dataset.autospin !== "done") {
        spin();
        el.dataset.autospin = "done";
      }
    }, 2000);
    el.addEventListener("mouseenter", spin);
    return () => {
      clearTimeout(fallback);
      el.removeEventListener("animationend", onAnimEnd);
      el.removeEventListener("mouseenter", spin);
    };
  }, []);

  return (
    <svg
      ref={ref}
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 64 64"
      fill="none"
      className={cn("rk-mark", className)}
      aria-label="RK"
    >
      <title>RK</title>
      <g transform="translate(-1.6 0)">
        <g stroke="currentColor" strokeWidth="5" strokeLinecap="butt">
          <path className="s1" d="M13.5 50V14" />
          <path className="s2" d="M13.5 14h8.5a9 9 0 0 1 0 18h-8.5" />
          <path className="s3" d="M21 32l10.5 18" />
          <path className="s4" d="M38.5 50V14" />
          <path className="s5" d="M38.5 33.5L52 50" />
        </g>
        <path
          className="swoop"
          d="M36.4 35.8 C 42.5 29.5, 48.5 22.5, 58 11.4 C 54 23, 47.5 30.5, 40.6 39.4 Z"
          fill="currentColor"
        />
      </g>
    </svg>
  );
}
