/**
 * Small status pill for the offline write queue.
 *
 * Renders nothing in the normal case (online, queue empty). When a save was
 * parked locally it says so; when a replay hit a 409 sha conflict it turns into
 * an amber warning, because that item will never retry on its own and the user
 * has to redo it against the newer server data.
 */
import { useCallback, useEffect, useState } from "react";
import { AlertTriangle, CloudOff, RefreshCw } from "lucide-react";

import { drainOfflineQueue } from "@/lib/api";
import { browserStore, queueStatus, subscribeQueue } from "@/lib/offline-queue";

export function OfflineBanner() {
  const [status, setStatus] = useState({ pending: 0, conflict: false });
  const [online, setOnline] = useState(() =>
    typeof navigator === "undefined" ? true : navigator.onLine,
  );
  const [syncing, setSyncing] = useState(false);

  const refresh = useCallback(() => {
    const store = browserStore();
    setStatus(store ? queueStatus(store) : { pending: 0, conflict: false });
  }, []);

  const sync = useCallback(() => {
    setSyncing(true);
    void drainOfflineQueue()
      .catch(() => undefined)
      .finally(() => {
        setSyncing(false);
        refresh();
      });
  }, [refresh]);

  useEffect(() => {
    refresh();
    const unsubscribe = subscribeQueue(refresh);
    function goOnline() {
      setOnline(true);
      sync();
    }
    function goOffline() {
      setOnline(false);
    }
    window.addEventListener("online", goOnline);
    window.addEventListener("offline", goOffline);
    // Drain on mount too: the browser may have come back while the tab was shut.
    sync();
    return () => {
      unsubscribe();
      window.removeEventListener("online", goOnline);
      window.removeEventListener("offline", goOffline);
    };
  }, [refresh, sync]);

  if (status.pending === 0 && online) return null;

  const warn = status.conflict;
  return (
    <div
      role="status"
      className={
        // bottom-20 keeps the pill clear of PwaInstallBanner, which spans the full
        // width at bottom-4 on phones and paints after us.
        "fixed bottom-20 left-4 z-40 flex items-center gap-2 rounded-full border px-3 py-1.5 text-xs shadow-lg backdrop-blur " +
        (warn
          ? "border-amber-500/40 bg-amber-500/15 text-amber-600 dark:text-amber-400"
          : "border-border/60 bg-card/90 text-muted-foreground")
      }
    >
      {warn ? (
        <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
      ) : syncing ? (
        <RefreshCw className="h-3.5 w-3.5 shrink-0 animate-spin" />
      ) : (
        <CloudOff className="h-3.5 w-3.5 shrink-0" />
      )}
      {warn ? (
        <span>
          {status.pending} saved {status.pending === 1 ? "entry" : "entries"} could not sync —
          someone else changed it. Re-enter it from the page.
        </span>
      ) : status.pending > 0 ? (
        <span>
          {status.pending} {status.pending === 1 ? "change" : "changes"} saved locally, will sync
        </span>
      ) : (
        <span>Offline — changes will be saved locally</span>
      )}
      {!warn && status.pending > 0 && online ? (
        <button
          type="button"
          onClick={sync}
          disabled={syncing}
          className="font-medium underline underline-offset-2 hover:text-foreground disabled:opacity-50"
        >
          Retry
        </button>
      ) : null}
    </div>
  );
}
