/**
 * Competitor price capture: roadside-sign units and observation freshness.
 *
 * Signs are in cents ("152.9"), every stored price is $/L (1.529). Both
 * conversions round at the 4th decimal of a dollar (= 2nd decimal of a cent),
 * which is the real precision of a pump sign, so 152.9 survives a round trip
 * instead of drifting to 1.5290000000000001.
 */

import type { Competitor, NearbyStation } from "./types";

/** Roadside cents/L → stored $/L. */
export function centsToPerL(cents: number): number {
  if (!Number.isFinite(cents) || cents <= 0) return 0;
  return Math.round(cents * 100) / 10000;
}

/** Stored $/L → roadside cents/L. */
export function perLToCents(perL: number): number {
  if (!Number.isFinite(perL) || perL <= 0) return 0;
  return Math.round(perL * 10000) / 100;
}

/**
 * These are human observations, not a feed. Anything older than this is shown
 * as stale so nobody reads a 14-hour-old sign as today's price.
 */
export const STALE_AFTER_MS = 12 * 60 * 60 * 1000;

export interface Observed {
  label: string; // "2h ago"
  stale: boolean;
}

/** Age of an observation, or null if it was never observed. */
export function observedAgo(iso: string | undefined, now = Date.now()): Observed | null {
  if (!iso) return null;
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return null;
  const ms = Math.max(0, now - t);
  const stale = ms >= STALE_AFTER_MS;
  const min = Math.floor(ms / 60000);
  if (min < 1) return { label: "just now", stale };
  if (min < 60) return { label: `${min}m ago`, stale };
  const h = Math.floor(min / 60);
  if (h < 48) return { label: `${h}h ago`, stale };
  return { label: `${Math.floor(h / 24)}d ago`, stale };
}

/** Manually-added competitors have no `tracked` flag; only an explicit false opts out. */
export function isTracked(c: Competitor): boolean {
  return c.tracked !== false;
}

/**
 * Fold a discovery run into the saved list. Re-running discovery must never
 * duplicate a station or throw away a choice the owner already made, so
 * matching is by `osmId` and the existing id/name/color always win — the
 * refreshed fields are only the ones OSM actually owns (address, coords).
 * Unselected stations are kept with `tracked: false` (opted out, not forgotten);
 * manual entries, which have no osmId, are never touched.
 */
export function mergeDiscovered(
  existing: Competitor[],
  stations: NearbyStation[],
  selectedOsmIds: Iterable<number>,
): Competitor[] {
  const selected = new Set(selectedOsmIds);
  const byOsm = new Map(stations.map((s) => [s.osmId, s]));
  const merged = existing.map((c) => {
    const s = c.osmId != null ? byOsm.get(c.osmId) : undefined;
    if (!s) return c;
    byOsm.delete(c.osmId!);
    return {
      ...c,
      brand: s.brand ?? c.brand,
      street: s.street ?? c.street,
      lat: s.lat,
      lng: s.lng,
      distanceKm: s.distanceKm,
      tracked: selected.has(s.osmId),
    };
  });
  for (const s of byOsm.values()) {
    if (!selected.has(s.osmId)) continue; // never seen, not wanted — don't clutter the config
    merged.push({
      id: `osm-${s.osmId}`,
      name: s.name,
      brand: s.brand,
      street: s.street,
      lat: s.lat,
      lng: s.lng,
      distanceKm: s.distanceKm,
      osmId: s.osmId,
      tracked: true,
    });
  }
  return merged;
}
